arguments.command:
du -h /workspace/experiment_logs/* /workspace/logs/* && python3 -I -c 'import gzip,re; p="/workspace/experiment_logs/stage_b.log.gz"; pats=re.compile(r"eval|pass@|pass_rate|passrate|rollout/|train/|critic-step|actor-step|truncat|response_len|abort|error|exception|nan",re.I); lines=[]
with gzip.open(p,"rt",errors="replace") as f:
 for i,s in enumerate(f,1):
  if pats.search(s): lines.append((i,s.rstrip()))
print("matched",len(lines)); print("\n".join(f"{i}: {s}" for i,s in lines[-350:]))'

