python3 -I -c 'import gzip,re
for p in ["/workspace/experiment_logs/stage_a.log.gz","/workspace/experiment_logs/stage_b.log.gz"]:
 print("FILE",p); pats=re.compile(r"Namespace\(|num_rollout|num_critic_only_steps|eval_interval|eval_config|start_rollout_id|advantage_estimator|normalize_advantages|use_rollout_logprobs|loss_mask|mask|calculate_per_token_loss|global_batch_size|rollout_batch_size|n_samples_per_prompt|lr=|value_clip|gamma|lambd",re.I)
 for i,s in enumerate(gzip.open(p,"rt",errors="replace"),1):
